def _taker_buying_24h_fade(
    close: np.ndarray,
    funding: np.ndarray,
    volume: np.ndarray,
    extras: dict[str, np.ndarray],
) -> np.ndarray:
    """-mean(taker buy/sell ratio over the three stamps ending BEFORE t).

    The one-stamp lag is registered: the endpoint's stamping convention
    (period start vs end) is ambiguous, and the lag makes the signal causal
    under either convention at the cost of 8h of staleness.
    """
    from services.backtesting.funding_factors import trailing_mean

    taker = extras["taker_buy_ratio"]
    lagged = np.full_like(taker, np.nan, dtype=float)
    lagged[1:] = taker[:-1]
    return np.asarray(-trailing_mean(lagged, 3), dtype=float)


def _trend_follow_7d(
    close: np.ndarray, funding: np.ndarray, volume: np.ndarray
) -> np.ndarray:
    """+(close_t / close_{t-21} - 1): RIDE the 7-day trend -- the plus sign
    the systematic fortunes were made on (registered 2026-08-29)."""
    signal = np.full_like(close, np.nan, dtype=float)
    with np.errstate(invalid="ignore", divide="ignore"):
        signal[21:] = close[21:] / close[:-21] - 1.0
    return signal


def _trend_follow_30d(
    close: np.ndarray, funding: np.ndarray, volume: np.ndarray
) -> np.ndarray:
    """+(close_t / close_{t-90} - 1): the longest trend the grid carries;
    the documented edge lives at 3-12 months, and the registration says so."""
    signal = np.full_like(close, np.nan, dtype=float)
    with np.errstate(invalid="ignore", divide="ignore"):
        signal[90:] = close[90:] / close[:-90] - 1.0
    return signal


def _near_high_fade(
    close: np.ndarray, funding: np.ndarray, volume: np.ndarray
) -> np.ndarray:
    """-(close_t / rolling 21-stamp max of close): fade contracts AT their
    own ~7-day high. The kernel of the 2026-08-28 external claim, causal by
    construction (the max window ends at t).

    ALL 21 closes must be finite: nanmax over a NaN-padded window would
    shrink the registered statistic, and a freshly listed perp's first stamp
    would score exactly -1.0 -- the fade extreme -- regardless of price,
    feeding new-listing drift into the record as a fake positive IC
    (adversarial review, 2026-08-28). A shorter window is a different
    variable than the registered one, so it is absent, never approximated.
    """
    signal = np.full_like(close, np.nan, dtype=float)
    n = close.shape[0]
    import warnings

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        for t in range(n):
            lo = max(0, t - 20)
            window = close[lo : t + 1]
            high_water = np.nanmax(window, axis=0)
            full = np.isfinite(window).sum(axis=0) >= 21
            with np.errstate(invalid="ignore", divide="ignore"):
                signal[t] = np.where(
                    full & (high_water > 0), -(close[t] / high_water), np.nan
                )
    return signal


def _blend_registered_v1(
    close: np.ndarray, funding: np.ndarray, volume: np.ndarray
) -> np.ndarray:
    """Frozen equal-weight z-score blend of the four 2026-07/08 factors.

    Weights are equal and FROZEN at registration (cb700cc): re-weighting
    after seeing which component performs would be selection wearing a
    blend. A cell where every component is absent stays absent.
    """
    from services.backtesting.cross_section import cross_sectional_zscore

    components = [
        _carry_signal(close, funding, volume),
        _reversal_8h(close, funding, volume),
        _momentum_72h_fade(close, funding, volume),
        _low_vol_7d(close, funding, volume),
    ]
    stack = np.stack([cross_sectional_zscore(c) for c in components])
    import warnings

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        blend = np.nanmean(stack, axis=0)
    blend[np.all(~np.isfinite(stack), axis=0)] = np.nan
    return np.asarray(blend, dtype=float)


