def compute_signal_ics(
    times_ms: np.ndarray,
    close: np.ndarray,
    signal: np.ndarray,
    horizon: int,
    min_history: int = 1,
) -> list[tuple[int, float, int]]:
    """Generic core: [(stamp_ms, ic, n_symbols)] for any signal matrix.

    A stamp is resolvable when its forward window has fully closed and the
    signal has *min_history* stamps behind it. Outcome is the cross-
    sectionally demeaned forward return, so market direction cannot score.
    Spearman is rank-based, so signal builders need no normalisation.
    """
    from scipy import stats

    results: list[tuple[int, float, int]] = []
    n_periods = times_ms.size
    for t in range(min_history - 1, n_periods - horizon):
        row = signal[t]
        entry = close[t]
        exit_ = close[t + horizon]
        usable = np.isfinite(row) & np.isfinite(entry) & np.isfinite(exit_)
        if int(usable.sum()) < _MIN_SYMBOLS:
            continue
        forward = exit_[usable] / entry[usable] - 1.0
        forward = forward - forward.mean()
        sig = row[usable]
        if sig.std() == 0 or forward.std() == 0:
            continue
        rho = stats.spearmanr(sig, forward)
        if np.isnan(rho.statistic):
            continue
        results.append((int(times_ms[t]), float(rho.statistic), int(usable.sum())))
    return results


def compute_resolvable_ics(
    times_ms: np.ndarray,
    close: np.ndarray,
    funding: np.ndarray,
    horizon: int = HORIZON_STAMPS,
    lookback: int = CARRY_LOOKBACK_STAMPS,
) -> list[tuple[int, float, int]]:
    """Pure core: [(stamp_ms, ic, n_symbols)] for every resolvable stamp.

    A stamp is resolvable when its forward window has fully closed AND the
    factor has a full lookback behind it. The factor is +trailing-mean
    funding (high funding scored high -- the registered sign); the outcome is
    the cross-sectionally demeaned forward return, so market direction
    cannot score.
    """
    import warnings

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        carry = np.stack(
            [
                np.nanmean(funding[max(0, t - lookback + 1) : t + 1], axis=0)
                for t in range(times_ms.size)
            ]
        )
    # The lookback gate is enforced via min_history so partial windows at the
    # start are never scored, matching the original behaviour exactly.
    return compute_signal_ics(times_ms, close, carry, horizon, min_history=lookback)


def _fetch_recent(
    max_stamps: int = _FETCH_STAMPS,
) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, dict[str, np.ndarray]]:
    """Blocking fetch of recent 8h closes + per-8h funding for live perps,
    plus the registered extra series (OI, long/short, taker ratio).

    Runs in a worker thread. Uses only public endpoints; no keys involved.
    """
    import time

    import ccxt

    exchange = ccxt.binance({"options": {"defaultType": "future"}, "enableRateLimit": True})
    markets = exchange.load_markets()
    symbols = sorted(
        s for s, m in markets.items()
        if m.get("swap") and m.get("linear") and m.get("active")
        and m.get("quote") == "USDT"
    )

    # The data endpoints serve 4h periods (no 8h option); fetch enough 4h
    # points to compose every 8h stamp on the grid.
    extra_limit = min(500, (max_stamps + HORIZON_STAMPS) * 2 + 4)

    per_symbol_bars: dict[str, dict[int, tuple[float, float]]] = {}
    per_symbol_funding: dict[str, dict[int, float]] = {}
    per_symbol_extras: dict[str, dict[str, dict[int, float]]] = {
        name: {} for name in _EXTRA_SERIES
    }
    attempts = dict.fromkeys(_EXTRA_SERIES, 0)
    errors = dict.fromkeys(_EXTRA_SERIES, 0)
    # One closure decision for the whole cycle: the throttled loop takes
    # minutes, and a bar closing mid-loop must not be included for only the
    # late-alphabet symbols (a biased cross-section at that stamp).
    now_ms = int(time.time() * 1000)
    for symbol in symbols:
        try:
            bars = exchange.fetch_ohlcv(symbol, "8h", limit=max_stamps + HORIZON_STAMPS)
            history = exchange.fetch_funding_rate_history(
                symbol, limit=(max_stamps + CARRY_LOOKBACK_STAMPS) * 2
            )
        except Exception:
            continue  # one flaky symbol must not kill the cycle
        per_symbol_bars[symbol] = _closed_bars(bars, now_ms)
        rates: dict[int, float] = {}
        for row in history:
            stamp = (int(row["timestamp"]) // _MS_8H) * _MS_8H
            info = row.get("info") or {}
            # Normalise to per-8h: some contracts settle every 4 hours.
            interval = float(info.get("fundingIntervalHours") or 8.0)
            rates[stamp] = float(row["fundingRate"]) * (8.0 / max(interval, 1e-9))
        per_symbol_funding[symbol] = rates

        market_id = markets[symbol]["id"]
        for name, (method, parse) in _EXTRA_SERIES.items():
            time.sleep(_DATA_FAMILY_MIN_INTERVAL_S)  # the family's own IP cap
            attempts[name] += 1
            try:
                rows = getattr(exchange, method)(
                    {"symbol": market_id, "period": "4h", "limit": extra_limit}
                )
            except Exception:
                errors[name] += 1
                continue  # a missing series must not cost the symbol its bars
            aligned = parse(rows)
            if aligned:
                per_symbol_extras[name][symbol] = aligned

    for name in _EXTRA_SERIES:
        if not _series_is_trustworthy(attempts[name], errors[name]):
            logger.warning(
                "extra_series_degraded",
                series=name,
                attempts=attempts[name],
                errors=errors[name],
            )
            per_symbol_extras[name] = {}

    grid = np.array(
        sorted({s for bars in per_symbol_bars.values() for s in bars})[-max_stamps:],
        dtype=np.int64,
    )
    kept = sorted(per_symbol_bars)
    close = np.full((grid.size, len(kept)), np.nan)
    volume = np.full((grid.size, len(kept)), np.nan)
    funding = np.full((grid.size, len(kept)), np.nan)
    extras = {
        name: np.full((grid.size, len(kept)), np.nan) for name in _EXTRA_SERIES
    }
    index_of = {stamp: i for i, stamp in enumerate(grid)}
    for j, symbol in enumerate(kept):
        for stamp, (price, vol) in per_symbol_bars[symbol].items():
            i = index_of.get(stamp)
            if i is not None:
                close[i, j] = price
                volume[i, j] = vol
        rates = per_symbol_funding.get(symbol, {})
        last = np.nan
        for i, stamp in enumerate(grid):
            if stamp in rates:
                last = rates[stamp]
            if np.isfinite(close[i, j]):
                funding[i, j] = last
        for name in _EXTRA_SERIES:
            for stamp, value in per_symbol_extras[name].get(symbol, {}).items():
                i = index_of.get(stamp)
                if i is not None:
                    extras[name][i, j] = value
    _blank_ragged_retention_edge(extras)
    return grid, close, funding, volume, extras


class FundingWatchService:
    """Background loop persisting the live IC record."""

    def __init__(self, session_factory: async_sessionmaker[AsyncSession]) -> None:
        self._session_factory = session_factory
        self._task: asyncio.Task[None] | None = None

    async def start(self) -> None:
        self._task = asyncio.create_task(self._run())
        logger.info("FundingWatchService started.")

    async def stop(self) -> None:
        if self._task is not None:
            self._task.cancel()

    async def _run(self) -> None:
        while True:
            try:
                inserted = await self.observe_once()
                logger.info("funding_watch_cycle", new_observations=inserted)
            except asyncio.CancelledError:
                break
            except Exception:
                logger.exception("funding_watch_cycle_failed")
            await asyncio.sleep(_CYCLE_SECONDS)

    async def observe_once(self) -> int:
        """Fetch once, then resolve and insert for EVERY registered factor."""
        grid, close, funding, volume, extras = await asyncio.to_thread(_fetch_recent)
        if grid.size == 0:
            return 0

        inserted = 0
        async with self._session_factory() as session:
            now = datetime.now(UTC)
            for factor in WATCHED_FACTORS:
                if factor.requires:
                    missing = [
                        key
                        for key in factor.requires
                        if key not in extras or not np.isfinite(extras[key]).any()
                    ]
                    if missing:
                        # Skipped, never fed garbage: an absent series must
                        # surface as a missing observation, not a wrong one.
                        logger.warning(
                            "factor_series_missing",
                            factor=factor.name,
                            missing=missing,
                        )
                        continue
                    signal = factor.build(close, funding, volume, extras)  # type: ignore[call-arg]
                else:
                    signal = factor.build(close, funding, volume)  # type: ignore[call-arg]
                candidates = compute_signal_ics(
                    grid, close, signal, HORIZON_STAMPS, factor.min_history
                )
                if not candidates:
                    continue
                existing = await self._existing_stamps(session, factor.name)
                for stamp_ms, ic, n_symbols in candidates:
                    when = datetime.fromtimestamp(stamp_ms / 1000, UTC)
                    if when < factor.unseen_from or when in existing:
                        continue
                    if (now - when).total_seconds() > _MAX_HEAL_DAYS * 86_400:
                        # A stamp this stale would be scored on TODAY's
                        # listing set: a visible gap beats a survivorship-
                        # tinted row (review, 2026-08-29).
                        continue
                    session.add(
                        FactorWatchObservation(
                            time=when,
                            factor=factor.name,
                            horizon_stamps=HORIZON_STAMPS,
                            ic=ic,
                            n_symbols=n_symbols,
                            resolved_at=now,
                        )
                    )
                    inserted += 1
            if inserted:
                await session.commit()
        return inserted

    async def _existing_stamps(
        self, session: AsyncSession, factor: str = FACTOR_NAME
    ) -> set[datetime]:
        result = await session.execute(
            select(FactorWatchObservation.time).where(
                FactorWatchObservation.factor == factor
            )
        )
        return {row[0].replace(tzinfo=UTC) if row[0].tzinfo is None else row[0]
                for row in result.all()}


def quarterly_rollup(
    observations: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Aggregate stamp ICs into calendar quarters for the adjudication view."""
    buckets: dict[str, list[float]] = {}
    for obs in observations:
        when: datetime = obs["time"]
        quarter = f"{when.year}-Q{(when.month - 1) // 3 + 1}"
        buckets.setdefault(quarter, []).append(float(obs["ic"]))
    rollup: list[dict[str, Any]] = []
    for quarter in sorted(buckets):
        values = np.array(buckets[quarter])
        mean = float(values.mean())
        std = float(values.std(ddof=1)) if values.size > 1 else 0.0
        t_stat = float(mean / std * np.sqrt(values.size)) if std > 0 else 0.0
        rollup.append(
            {
                "quarter": quarter,
                "n": int(values.size),
                "mean_ic": mean,
                "t_stat": t_stat,
                "positive": mean > 0,
            }
        )
    return rollup
